layer.css:
@import url("https://fonts.googleapis.com/css2?family=IBM+Plex+Mono:ital,wght@0,300;0,400;0,500;0,600;0,700;1,300;1,600&display=swap");
[data-ryt="pitch"] { color: var(--ryt-text); border-left: 2px solid var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 15px; font-weight: 300; font-style: italic; line-height: 1.95; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 22px; transition: all; border-top: none; border-right: none; border-bottom: none }
article[data-ryt="rec-card"] { border-bottom: 1px solid color-mix(in srgb, var(--ryt-text) 40%, transparent); border-radius: 0px; transition: all; border-top: none; border-right: none; border-left: none }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-text); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-line: underline; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: 1px; text-underline-offset: 4px; transition: all }
[data-ryt="section"] > h2 { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 700; font-style: normal; line-height: 1.15; letter-spacing: -1.56px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="review"] { color: var(--ryt-text); font-family: var(--ryt-font-heading); font-size: 13px; font-weight: 300; font-style: normal; line-height: 1.8; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: var(--ryt-text); font-family: var(--ryt-font-heading); font-size: 11px; font-weight: 300; font-style: normal; line-height: 1.95; letter-spacing: 1.98px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 600; font-style: normal; letter-spacing: -0.18px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: 4px; transition: all }
[data-ryt="button"] { color: var(--ryt-text); background-color: var(--ryt-bg); border-top: 1px solid var(--ryt-text); border-right: 1px solid var(--ryt-text); border-bottom: 1px solid var(--ryt-text); border-left: 1px solid var(--ryt-text); border-radius: 0px; font-family: Arial; font-weight: 400; font-style: normal; line-height: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: background 0.2s, color 0.2s }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 18px; font-weight: 600; font-style: normal; line-height: 1.95; letter-spacing: -0.18px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: 4px; transition: all }
[data-ryt="rec-card"] [data-ryt="title"]:hover { text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
[data-ryt="button"]:hover { color: #05366e }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
[data-ryt="credit"] a:hover, [data-ryt="review"] a:hover, [data-ryt="bio"] a:hover { text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
